function openIdx(city){var m=document.getElementById("idxModal");if(!m)return;if(city){var s=document.getElementById("idxCity");if(s){for(var i=0;i<s.options.length;i++){if(s.options[i].value===city){s.selectedIndex=i;break;}}}}m.classList.add("open");document.body.style.overflow="hidden";}function closeIdx(){var m=document.getElementById("idxModal");if(m){m.classList.remove("open");document.body.style.overflow="";}}function idxPill(el){el.classList.toggle("on");}function idxSearch(){var cc=document.getElementById("idxConsent");if(cc&&!cc.checked){cc.style.outline="2px solid #c0392b";return;}var em=document.getElementById("idxEmail");var v=em.value.trim();if(!v||v.indexOf("@")<1){em.style.borderColor="#c0392b";return;}var t=[].slice.call(document.querySelectorAll("#idxModal .idx-pill.on")).map(function(p){return p.textContent;});var a=[].slice.call(document.querySelectorAll("#idxModal .idx-amen:checked")).map(function(c){return c.value;});var crit="City: "+document.getElementById("idxCity").value+" | Type: "+(t.join(", ")||"Any")+" | Price: "+document.getElementById("idxMin").value+" to "+document.getElementById("idxMax").value+" | Beds: "+document.getElementById("idxBeds").value+" | Baths: "+document.getElementById("idxBaths").value+" | Lot: "+document.getElementById("idxLot").value+" | MinSqFt: "+document.getElementById("idxSqft").value+" | Amenities: "+(a.join(", ")||"None");if(typeof c3SendForm==="function"){c3SendForm({name:document.getElementById("idxName").value,email:v,phone:document.getElementById("idxPhone").value,listing_criteria:crit},"IDX Listing Search");}document.getElementById("idxForm").style.display="none";document.getElementById("idxOk").style.display="block";}function idxQuick(){var sy=function(s,d){var a=document.getElementById(s),b=document.getElementById(d);if(a&&b){for(var i=0;i<b.options.length;i++){if(b.options[i].value===a.value){b.selectedIndex=i;break;}}}};sy("q_city","idxCity");sy("q_beds","idxBeds");sy("q_baths","idxBaths");sy("q_min","idxMin");sy("q_max","idxMax");var it=[].slice.call(document.querySelectorAll(".q-type:checked")).map(function(c){return c.value;}).concat([].slice.call(document.querySelectorAll(".qs-chip.on")).map(function(c){return c.getAttribute("data-v");}));[].slice.call(document.querySelectorAll("#idxModal .idx-pill")).forEach(function(p){if(it.indexOf(p.textContent)>=0)p.classList.add("on");else p.classList.remove("on");});openIdx();}document.addEventListener("keydown",function(e){if(e.key==="Escape")closeIdx();});